// The detail boxes (T0093 Layer 1): a word on the pane (a weapon, a spell, a
// save, a skill, a resource, a condition, the last-seen value, the requests)
// opens one box under its row, one at a time. Pure: no mods API. Everything a
// box says is data the pane already holds (the sheet, `derived`, facts.ts);
// it applies no rule. A breakdown (`CON +4 = CON +2 · proficient +2`) is the
// server's numbers taken apart by subtraction, which is display.
//
// A word's key names its subject: `w:act:<row key>` (actions.ts's row keys),
// `w:save:<ability>`, `w:skill:<name>`, `w:res:<index>` on the focused sheet;
// `w:cond:<entry id>:<condition>`, `w:seen:<entry id>`, `w:req:<entry id>` on
// any cached sheet. A word is drawn only where `detailOf` has a box for it.
//
// Inside a box (Layer 2) a rules term is a word too. `w:n:<target>` nests: its
// press pushes `w:<target>` onto the open box's path (`w:n:g:heavy` opens the
// glossary's Heavy in place, `w:n:skill:Athletics` the skill's box), the title
// becomes the path's breadcrumb and `[ ‹ ]` pops a level. `w:c:<kind>:<name>`
// opens T0085's card, which the rules server fills: `w:c:spell:<name>`,
// `w:c:monster:<name>`, `w:c:option:<kind>|<name>|<feature>[|<row>]` (character_option_get).

import type { Elements, RenderElement, RenderNode } from 'claude-code'
import { cantripDice, mastery, norm, sameWeapon, spellFact, weaponFact, writtenDamage } from './actions.ts'
import { SKILLS, SKILLS_CITE, SPELL_ALIASES, SPELLS } from './facts.ts'
import { GLOSSARY } from './glossary.ts'
import { CONDITIONS, SCHOOLS, type Candidate, type Card } from './lookup.ts'
import { TOKENS } from './look.ts'
import { describeChange, type Entry } from './sheet.ts'

/**
 * The open box: the word it hangs from, and the terms opened inside it, the
 * anchor first. `above`: a pinned preview (Layer 3), drawn above the word, not under its row.
 */
export type Detail = { anchor: string; path: string[]; above?: true }

/**
 * The hover preview (Layer 3): the word's card above it, and a term's card
 * above that (one level on hover); `pinned` once a click locked it.
 */
export type Preview = { anchor: string; top: Content; nested: Content | null; pinned: boolean }

/** The deepest a box nests: at this depth its words are plain text. */
const DEPTH = 3

/**
 * A press on a word: its box opens, replacing any other; a press on the open
 * one closes it. A term inside the open box (`w:n:`) nests its box on the path,
 * while the path is shallower than DEPTH and does not hold it already.
 */
export const pressWord = (state: Detail | null, key: string): Detail | null => {
  if (!key.startsWith('w:n:')) return state?.anchor === key ? null : { anchor: key, path: [key] }
  const to = 'w:' + key.slice('w:n:'.length)
  return state && state.path.length < DEPTH && !state.path.includes(to) ? { ...state, path: [...state.path, to] } : state
}

/** A `w:c:` word's card, or null for any other key. */
export function wordCard(key: string): Candidate | null {
  const m = /^w:c:(spell|monster|option):(.+)$/.exec(key)
  if (!m) return null
  const [, kind, rest] = m as unknown as [string, 'spell' | 'monster' | 'option', string]
  if (kind === 'option') {
    // Only a class or subclass takes one feature; any other option opens whole.
    // A species' card shows the pressed trait (its name the candidate's), from
    // the one answer. A fourth part, the row, only keeps each word's key its own.
    const [k, name, feature] = rest.split('|')
    const one = k === 'class' || k === 'subclass' ? feature : ''
    return { name: one || (k === 'species' && feature) || name!, kind, key: `${k}|${name}|${one}` }
  }
  return { name: rest, kind, key: kind === 'spell' ? norm(rest) + '|xphb' : norm(rest) }
}

/** A run of a line: values bold, labels faint, a warning amber; with a `key`, a word. */
export type Piece = { text: string; tone?: 'value' | 'label' | 'warn'; key?: string }
/** Pieces that never break apart; a line wraps only between units. */
type Unit = Piece[]

export interface Content {
  title: string
  lines: Unit[][]
  /** Where it comes from: `XPHB · derived`, `derived`, `sheet`. */
  cite: string
  /** `[ more ]`: T0085's card for this term. */
  more: Candidate | null
  /** `[ re-read ]`: the sheet's re-read. */
  reread: boolean
  /** `[ ‹ ]`: the box is nested; it pops a level. */
  back?: boolean
  /** Long text: past six rows it ends at a sentence, and `[ more ]` shows the rest (no `[ more ]` when it fits). */
  cut?: boolean
}

const val = (text: string): Piece => ({ text, tone: 'value' })
const lab = (text: string): Piece => ({ text, tone: 'label' })
const warn = (text: string): Piece => ({ text, tone: 'warn' })
const plain = (text: string): Piece => ({ text })
/** Units joined by a faint ` ·` at the end of each but the last. */
const dots = (units: Unit[]): Unit[] => units.map((u, i) => (i < units.length - 1 ? [...u, lab(' ·')] : u))
/** Prose as one unit a word, so it wraps between words. */
const prose = (s: string, tone?: Piece['tone']): Unit[] =>
  s
    .split(/\s+/)
    .filter(Boolean)
    .map((w) => [{ text: w, ...(tone ? { tone } : {}) }])

const signed = (n: number) => (n >= 0 ? '+' + n : String(n))
const num = (x: unknown): number | null => {
  const n = typeof x === 'number' ? x : typeof x === 'string' && x.trim() ? Number(x) : NaN
  return Number.isFinite(n) ? n : null
}
const ORDINAL = (l: number) => ({ 1: '1st', 2: '2nd', 3: '3rd' })[l] ?? l + 'th'
const pad2 = (n: number) => String(n).padStart(2, '0')
const clock = (ms: number) => pad2(new Date(ms).getHours()) + ':' + pad2(new Date(ms).getMinutes())
const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC']
/** `39 min`, `5 h`, `3 d`. */
const ago = (ms: number) => {
  const m = Math.max(0, Math.round(ms / 60000))
  return m < 60 ? `${m} min` : m < 48 * 60 ? `${Math.round(m / 60)} h` : `${Math.round(m / 1440)} d`
}
/** The pending number's warning: `derived` is the server's, and a write since may change it. */
const PENDING: Unit[] = prose('the server has not derived this yet', 'warn')

/** A glossary term, a word that nests its entry; plain where the glossary has none (Ritual). */
const term = (text: string, tone?: Piece['tone'], key = text.toLowerCase()): Piece => ({ text, ...(tone ? { tone } : {}), ...(GLOSSARY[key] ? { key: 'w:n:g:' + key } : {}) })

/** The fetch kinds a glossary link names (build.py's FETCH_KINDS), as the word each is; `classFeature` names no class, so stays text. */
const FETCH: Record<string, (name: string) => string> = {
  spell: (n) => 'w:c:spell:' + n,
  creature: (n) => 'w:c:monster:' + n,
  item: (n) => 'w:c:option:item|' + n + '|',
  feat: (n) => 'w:c:option:feat|' + n + '|',
  skill: (n) => 'w:n:skill:' + n,
}
/** A link in glossary text, `⟦key|shown⟧` or `⟦kind:name|shown⟧`, as its word. */
function link(target: string, shown: string): Piece {
  const at = target.indexOf(':')
  if (at < 0) return { text: shown, key: 'w:n:g:' + target }
  const to = FETCH[target.slice(0, at)]
  return to ? { text: shown, key: to(target.slice(at + 1)) } : plain(shown)
}
/**
 * Glossary text as lines of units: words wrap apart; a link and the punctuation
 * touching it stay one unit. A link to a target already linked is text: a key
 * is drawn once (Light's three Bonus Actions).
 */
const glossLines = (text: string): Unit[][] => {
  const linked = new Set<string>()
  return text.split('\n').map((line) => {
    const units: Unit[] = []
    let cur: Unit = []
    const flush = () => (cur.length && units.push(cur), (cur = []))
    for (const part of line.split(/(⟦[^⟧]*⟧)/)) {
      const m = /^⟦([^|⟧]*)\|([^⟧]*)⟧$/.exec(part)
      if (m) cur.push(linked.has(m[1]!) ? plain(m[2]!) : (linked.add(m[1]!), link(m[1]!, m[2]!)))
      else for (const w of part.split(/(\s+)/)) /^\s+$/.test(w) ? flush() : w && cur.push(plain(w))
    }
    flush()
    return units
  })
}

/** A glossary entry (`w:g:<key>`): its SRD 5.2.1 text and page, cut long with `[ more ]` to the whole. */
function glossaryBox(key: string): Content | null {
  const g = GLOSSARY[key]
  if (!g) return null
  const [title, text, source, page] = g
  return { title, lines: glossLines(text), cite: `${source} p.${page}`, more: { name: title, kind: 'glossary', key }, reread: false, cut: true }
}

/**
 * `ABIL +mod`, then what proficiency adds, then any rest: the server's total
 * taken apart. `prof` is 0 (none), 1 (proficient) or 2 (expertise).
 */
function breakdown(total: number, abil: string, d: Record<string, any>, prof: 0 | 1 | 2): Unit[] {
  const mod = num(d.modifiers?.[abil])
  const pb = num(d.proficiency_bonus)
  if (mod === null || (prof && pb === null)) return []
  const add = prof ? prof * pb! : 0
  const rest = total - mod - add
  return [
    [lab(abil.toUpperCase() + ' '), val(signed(mod))],
    ...(prof ? [[lab(prof === 2 ? 'expertise ' : 'proficient '), val(signed(add))]] : []),
    ...(rest ? [[lab('other '), val(signed(rest))]] : []),
  ]
}

// ------------------------------------------------------------------ the boxes

function weaponBox(e: Entry, n: number): Content | null {
  const item = (e.sheet.inventory ?? [])[n]
  if (!item) return null
  const name = String(item.name ?? '')
  const hit = weaponFact(name, item.source, e.sheet.ruleset)
  if (!hit) return null
  const [category, kind, dice, type, versatile, props, range, masteryName] = hit.row
  const d = e.derived ?? {}
  const dw = (Array.isArray(d.weapons) ? d.weapons : []).find((w: any) => sameWeapon(String(w?.name ?? ''), name))
  const lines: Unit[][] = []
  const attack = num(dw?.attack)
  if (dw && attack !== null) {
    const prof = dw.proficient !== false
    lines.push(dots([[val(signed(attack)), plain(' to hit')], ...breakdown(attack, String(dw.ability ?? ''), d, prof ? 1 : 0), ...(prof ? [] : [[lab('not proficient')]])]))
  }
  const own = writtenDamage(String(item.note ?? ''))
  lines.push(own ? dots([[val(own)], [lab('as written')]]) : dots([[val([dice, type].filter(Boolean).join(' '))], [lab('no damage written'), warn(' ?')]]))
  // The two-handed dice with the attack's ability modifier, as the design's `two-handed 1d10+2`.
  const vmod = num(d.modifiers?.[String(dw?.ability ?? '')])
  if (versatile) lines.push([[lab('two-handed '), val(versatile + (vmod ? signed(vmod) : ''))]])
  const score = (abil: string) => num(e.sheet.abilities?.[abil])
  const heavy = kind === 'ranged' ? 'dex' : 'str'
  lines.push(
    dots([
      [val(category)],
      [val(kind)],
      ...(props ? props.split(',') : []).map((p): Unit => {
        if ((p === 'Thrown' || p === 'Ammunition') && range) return [term(p, 'value'), val(' ' + range)]
        if (p === 'Heavy' && score(heavy) !== null) return [term('Heavy', 'value'), lab(` (your ${heavy.toUpperCase()} ${score(heavy)})`)]
        return [term(p, 'value')]
      }),
    ]),
  )
  const wm = mastery(e)
  if (masteryName && wm && (wm.all || wm.names.some((w) => sameWeapon(w, name)))) lines.push([[lab('mastery '), term(masteryName, 'value')]])
  const says = Object.entries((e.sheet.as_written?.weapon_attack ?? {}) as Record<string, unknown>).find(([k]) => sameWeapon(k, name))?.[1]
  if (dw && says !== undefined && String(says) !== String(dw.attack)) lines.push([[lab('the sheet says '), val(String(says))]])
  if (dw && e.derivedPending) lines.push(PENDING)
  return { title: name, lines, cite: hit.source + (dw ? ' · derived' : ''), more: null, reread: false }
}

function spellBox(e: Entry, spell: any, cls: string): Content | null {
  const name = String(spell?.name ?? '')
  const hit = spellFact(name, spell?.source, e.sheet.ruleset)
  if (!hit) return null
  const [level, school, time, range, comps, duration, flagText, damage, save, diceText] = hit.row
  const flags = flagText ? flagText.split(' ') : []
  const d = e.derived ?? {}
  const lines: Unit[][] = [dots([level === 0 ? 'Cantrip' : ORDINAL(level), SCHOOLS[school] ?? school, time, range, comps, duration].filter(Boolean).map((s) => [val(s)]))]
  const caster = cls ? ((d.spellcasting ?? []) as any[]).find((c) => String(c.class) === cls) : undefined
  const q = e.derivedPending ? '?' : ''
  if (caster && (flags.includes('melee') || flags.includes('ranged'))) {
    const atk = num(caster.attack)
    lines.push([[val((atk === null ? String(caster.attack) : signed(atk)) + q), plain(' to hit')], [lab(`(${cls})`)]])
  } else if (caster && save) lines.push(dots([[val(save), plain(' '), term('save', undefined, 'saving throw')], [lab('DC '), val(String(caster.save_dc) + q), lab(` (${cls})`)]]))
  const total = num(d.total_level)
  const dice = level === 0 ? cantripDice(diceText, total) : diceText
  if (damage) lines.push([[val(dice)], ...prose(damage.split(',').join(', '))].filter((u) => u[0]!.text))
  else if (flags.includes('heal') && dice) lines.push([[lab('heal '), val(dice + (flags.includes('mod') ? ' + mod' : ''))]])
  const tags = [...(flags.includes('conc') ? ['Concentration'] : []), ...(flags.includes('ritual') ? ['Ritual'] : [])]
  if (tags.length) lines.push(dots(tags.map((t) => [term(t, 'value')])))
  if (caster && e.derivedPending) lines.push(PENDING)
  // The card fetches the spell by name; the facts row is the one this box read.
  const n = norm(name)
  const keyName = SPELLS[n + '|' + hit.source.toLowerCase()] ? n : SPELL_ALIASES[n] ?? n
  return { title: name, lines, cite: hit.source + (caster ? ' · derived' : ''), more: { name, kind: 'spell', key: keyName + '|' + hit.source.toLowerCase() }, reread: false }
}

/** `w:act:<row key>`: `weapon-<inventory index>`, `spell-<class>-c<i>` (cantrip), `spell-<class>-<i>`, `other-<i>`. */
function actionBox(e: Entry, row: string): Content | null {
  const at = row.lastIndexOf('-')
  const kind = row.slice(0, row.indexOf('-'))
  const i = row.slice(at + 1)
  if (kind === 'weapon') return weaponBox(e, Number(i))
  if (kind === 'other') return spellBox(e, (e.sheet.spellcasting?.other ?? [])[Number(i)], '')
  if (kind !== 'spell') return null
  const cls = row.slice('spell-'.length, at)
  const sc = (e.sheet.spellcasting?.by_class ?? []).find((c: any) => String(c.class ?? '') === cls)
  const spell = i.startsWith('c') ? sc?.cantrips?.[Number(i.slice(1))] : sc?.spells?.[Number(i)]
  return spell ? spellBox(e, spell, cls) : null
}

function saveBox(e: Entry, abil: string): Content | null {
  const d = e.derived
  const total = num(d?.saving_throws?.[abil])
  if (!d || total === null) return null
  const prof = (e.sheet.proficiencies?.saves ?? []).includes(abil)
  const parts = breakdown(total, abil, d, prof ? 1 : 0)
  const lines: Unit[][] = [[[lab(abil.toUpperCase() + ' '), val(signed(total)), plain(parts.length ? ' =' : '')], ...dots(parts)]]
  if (e.derivedPending) lines.push(PENDING)
  return { title: abil.toUpperCase() + ' save', lines, cite: 'derived', more: null, reread: false }
}

function skillBox(e: Entry, skill: string): Content | null {
  const d = e.derived
  const name = Object.keys(d?.skills ?? {}).find((k) => k.toLowerCase() === skill.toLowerCase())
  const total = name ? num(d!.skills[name]) : null
  const abil = SKILLS[skill.toLowerCase()]
  if (!d || !name || total === null || !abil) return null
  const p = (e.sheet.proficiencies?.skills ?? []).find((k: any) => String(k.name).toLowerCase() === skill.toLowerCase())
  const parts = breakdown(total, abil, d, p ? (p.expertise ? 2 : 1) : 0)
  const lines: Unit[][] = [[[lab(name + ' '), val(signed(total)), plain(parts.length ? ' =' : '')], ...dots(parts)]]
  const says = Object.entries((e.sheet.as_written?.skills ?? {}) as Record<string, unknown>).find(([k]) => k.toLowerCase() === skill.toLowerCase())?.[1]
  if (says !== undefined && String(says) !== signed(total)) lines.push([[lab('the sheet says '), val(String(says))]])
  if (e.derivedPending) lines.push(PENDING)
  return { title: name, lines, cite: SKILLS_CITE + ' · derived', more: null, reread: false }
}

const RECHARGE: Record<string, string> = { long: 'a Long Rest', short: 'a Short Rest' }

function resourceBox(e: Entry, i: number): Content | null {
  const r = (e.sheet.resources ?? [])[i]
  const max = num(r?.max)
  if (!r || max === null) return null
  const lines: Unit[][] = [
    dots([[val(`${Math.max(0, max - (num(r.used) ?? 0))} of ${max}`)], ...(r.recharge ? [[lab('recharges on '), val(RECHARGE[r.recharge] ?? String(r.recharge))]] : [])]),
  ]
  if (r.note) lines.push(prose(String(r.note)))
  return { title: String(r.name), lines, cite: 'sheet', more: null, reread: false }
}

/** A condition on the sheet: exhaustion's level, then the rule from the glossary (no duration field exists yet). */
function conditionBox(e: Entry, cond: string): Content | null {
  const known = CONDITIONS.find((c) => norm(c) === norm(cond))
  if (!known) return null
  const level = num(e.sheet.exhaustion) ?? 0
  const ok = known === 'Exhaustion' ? level > 0 : (e.sheet.conditions ?? []).some((c: unknown) => norm(String(c)) === norm(cond))
  const rule = ok && glossaryBox(known.toLowerCase())
  if (!rule) return null
  return {
    ...rule,
    lines: [...(known === 'Exhaustion' ? [[[lab('level '), val(String(level))]]] : []), ...rule.lines],
    cite: rule.cite + ' · sheet',
  }
}

function seenBox(e: Entry, now: number): Content {
  const today = new Date(e.readAt).toDateString() === new Date(now).toDateString()
  const at = today ? clock(e.readAt) : `${new Date(e.readAt).getDate()} ${MONTHS[new Date(e.readAt).getMonth()]}, ${clock(e.readAt)}`
  const lines: Unit[][] = [[[lab('seen '), val(at)], [lab(`(${ago(now - e.readAt)})`)]]]
  if (e.last) lines.push([[lab('last')], ...prose(describeChange(e.last, e.sheet))])
  return { title: e.name, lines, cite: 'sheet', more: null, reread: true }
}

/** The DM's requests on a sheet (T0084): one line each; the pane decides nothing. */
function requestBox(e: Entry): Content | null {
  const reqs = Array.isArray(e.sheet.requests) ? e.sheet.requests : []
  if (!reqs.length) return null
  // Each field's words wrap apart; a faint ` ·` follows a field's last word.
  const lines: Unit[][] = reqs.map((r: any) =>
    [r?.ask, Array.isArray(r?.keys) ? r.keys.join(', ') : r?.keys, r?.by, r?.date]
      .filter((x) => x !== undefined && x !== null && String(x).trim())
      .map((x) => prose(String(x)))
      .flatMap((us, i, all) => (i < all.length - 1 ? [...us.slice(0, -1), [...us.at(-1)!, lab(' ·')]] : us)),
  )
  lines.push(prose('decide in chat', 'label'))
  return { title: `${e.name} · ${reqs.length} request${reqs.length === 1 ? '' : 's'}`, lines, cite: 'sheet', more: null, reread: false }
}

/** What a word's box holds, or null when it has none (the word is then plain text). */
export function detailOf(key: string, rows: Entry[], focused: Entry | null, now: number): Content | null {
  const [w, kind] = key.split(':', 2)
  if (w !== 'w' || !kind) return null
  const rest = key.slice(`w:${kind}:`.length)
  const byId = (id: string) => [...(focused ? [focused] : []), ...rows].find((e) => e.id === id) ?? null
  switch (kind) {
    case 'act':
      return focused ? actionBox(focused, rest) : null
    case 'save':
      return focused ? saveBox(focused, rest) : null
    case 'skill':
      return focused ? skillBox(focused, rest) : null
    case 'res':
      return focused ? resourceBox(focused, Number(rest)) : null
    case 'cond': {
      const at = rest.lastIndexOf(':')
      const e = byId(rest.slice(0, at))
      return e ? conditionBox(e, rest.slice(at + 1)) : null
    }
    case 'seen': {
      const e = byId(rest)
      return e ? seenBox(e, now) : null
    }
    case 'req': {
      const e = byId(rest)
      return e ? requestBox(e) : null
    }
    case 'g':
      return glossaryBox(rest)
    case 'n':
      return detailOf('w:' + rest, rows, focused, now)
    default:
      return null
  }
}

/**
 * The open box: the top of `path`, titled with the whole path (`Greatsword ›
 * Heavy › Disadvantage`), `[ ‹ ]` while nested. A word stays a word only once
 * per box, never to a box already on the path, never at the last depth, and
 * only where it opens something.
 */
export function detailAt(path: string[], rows: Entry[], focused: Entry | null, now: number): Content | null {
  const all = path.map((k) => detailOf(k, rows, focused, now))
  const top = all.at(-1)
  if (!top) return null
  const taken = new Set(path)
  const live = (k: string) => {
    const to = k.startsWith('w:n:') ? 'w:' + k.slice('w:n:'.length) : k
    if (path.length >= DEPTH || taken.has(to) || !(k.startsWith('w:c:') || detailOf(k, rows, focused, now))) return false
    taken.add(to)
    return true
  }
  const lines = top.lines.map((l) => l.map((u) => u.map(({ key, ...p }) => (key && live(key) ? { ...p, key } : p))))
  return { ...top, title: all.map((c) => c?.title ?? '…').join(' › '), lines, back: path.length > 1 }
}

// ------------------------------------------------------------------ drawing

type El = Pick<Elements['mobile'], 'Box' | 'Text'>
type Make = (props: { key: string; label: string }) => RenderElement
/** Draws a keyed piece as its word (view.ts's `word`), which falls back to plain text. */
type Word = (key: string, label: string, style: { bold?: true; dimColor?: true; color?: string }) => RenderNode

/** A piece's style: values bold, labels faint, a warning amber. */
const look = (p: Piece): { bold?: true; dimColor?: true; color?: string } =>
  p.tone === 'value' ? { bold: true } : p.tone === 'label' ? { dimColor: true } : p.tone === 'warn' ? { color: TOKENS.amber } : {}

/** The most body rows a box draws; past it, a faint `and N more`, or long text's sentence cut (never `…`). */
const MAX_ROWS = 6
const width = (u: Unit) => u.reduce((n, p) => n + p.text.length, 0)
const SENTENCE_END = /[.!?]["”’)\]]*$/

/**
 * Items in rows of at most `w` columns, `gap` between them: the greedy wrap.
 * Each row is drawn as its own nowrap row (the spike's line layout), since
 * flex shrink would split a word and `flexWrap` alone hides the columns.
 */
export function greedy<T>(items: T[], width: (t: T) => number, w: number, gap = 1): T[][] {
  const rows: T[][] = []
  let cur: T[] = []
  let used = 0
  for (const t of items) {
    const tw = width(t)
    if (cur.length && used + gap + tw > w) {
      rows.push(cur)
      cur = []
      used = 0
    }
    used += (cur.length ? gap : 0) + tw
    cur.push(t)
  }
  if (cur.length) rows.push(cur)
  return rows
}

/**
 * The body's rows at `w` columns, at most six: past them long text ends at a
 * sentence (`cut`), any other drops whole lines and counts them in `more`.
 */
function bodyRows(c: Content, w: number): { rows: Unit[][]; more: number; cut: boolean } {
  const laid = c.lines.map((l) => greedy(l, width, w))
  if (laid.reduce((n, rs) => n + rs.length, 0) <= MAX_ROWS) return { rows: laid.flat(), more: 0, cut: false }
  if (c.cut) {
    // The first six rows, ended after their last sentence; `[ more ]` has the rest.
    const ends = (u: Unit) => SENTENCE_END.test(u.at(-1)?.text ?? '')
    const rows = laid.flat().slice(0, MAX_ROWS)
    const r = rows.findLastIndex((row) => row.some(ends))
    return { rows: r < 0 ? rows : [...rows.slice(0, r), rows[r]!.slice(0, rows[r]!.findLastIndex(ends) + 1)], more: 0, cut: true }
  }
  const rows: Unit[][] = []
  let k = 0
  for (; k < laid.length && rows.length + laid[k]!.length <= MAX_ROWS - 1; k++) rows.push(...laid[k]!)
  return { rows, more: laid.length - k, cut: false }
}

/**
 * The box: a round border as wide as the pane's body, the title (the path's
 * breadcrumb), `[ ‹ ]` while nested and `[ × ]`, up to six rows (each a
 * nowrap row the wrap laid out), then `[ more ]` or `[ re-read ]` and the
 * faint cite at the bottom right. A keyed piece is drawn by `word`. Its
 * Buttons carry no hotkey.
 */
export function detailBox(el: El, make: Make, c: Content, columns: number, word: Word): RenderElement {
  const inner = Math.max(8, columns - 4)
  const span = (p: Piece) => (p.key ? word(p.key, p.text, look(p)) : el.Text({ children: [p.text], ...look(p) }))
  const drawRow = (r: Unit[]) =>
    el.Box({ flexDirection: 'row', columnGap: 1, children: r.map((u) => el.Box({ flexDirection: 'row', flexShrink: 0, children: u.map(span) })) })
  const { rows, more, cut } = bodyRows(c, inner)
  const body: RenderNode[] = rows.map(drawRow)
  if (more) body.push(el.Text({ children: [`and ${more} more`], dimColor: true }))
  const buttons = [...(c.more && (!c.cut || cut) ? [make({ key: 'detail-more', label: 'more' })] : []), ...(c.reread ? [make({ key: 'detail-reread', label: 're-read' })] : [])]
  return el.Box({
    key: 'detail',
    borderStyle: 'round',
    width: columns,
    paddingX: 1,
    flexDirection: 'column',
    children: [
      el.Box({
        flexDirection: 'row',
        columnGap: 1,
        children: [
          el.Box({ flexGrow: 1, flexShrink: 1, children: [el.Text({ children: [c.title], bold: true, wrap: 'wrap' })] }),
          ...(c.back ? [el.Box({ flexShrink: 0, children: [make({ key: 'detail-back', label: '‹' })] })] : []),
          el.Box({ flexShrink: 0, children: [make({ key: 'detail-x', label: '×' })] }),
        ],
      }),
      ...body,
      el.Box({
        flexDirection: 'row',
        justifyContent: buttons.length ? 'space-between' : 'flex-end',
        columnGap: 1,
        children: [...(buttons.length ? [el.Box({ flexDirection: 'row', columnGap: 1, children: buttons })] : []), el.Text({ children: [c.cite], dimColor: true })],
      }),
    ],
  })
}

// ------------------------------------------------------------------ the preview

/** One run of a preview row, as card.tsx draws it: a `key` makes it a term. */
export type Cell = { text: string; bold?: true; dimColor?: true; color?: string; key?: string }

/**
 * A box as the preview's rows at `columns` (card.tsx pads a column each side):
 * the title, the body as the box lays it out, the faint cite. `more`: the box
 * would draw `[ more ]`, which the preview draws once pinned.
 */
export function cardRows(c: Content, columns: number): { rows: Cell[][]; more: boolean } {
  const inner = Math.max(8, columns - 2)
  const cell = (p: Piece): Cell => ({ text: p.text, ...look(p), ...(p.key ? { key: p.key } : {}) })
  const line = (r: Unit[]): Cell[] => r.flatMap((u, i) => [...(i ? [{ text: ' ' }] : []), ...u.map(cell)])
  const { rows, more, cut } = bodyRows(c, inner)
  const faint = (text: string): Cell[] => [{ text, dimColor: true }]
  return {
    rows: [
      ...greedy(c.title.split(' '), (w) => w.length, inner).map((ws): Cell[] => [{ text: ws.join(' '), bold: true }]),
      ...rows.map(line),
      ...(more ? [faint(`and ${more} more`)] : []),
      ...(c.cite ? [faint(c.cite)] : []),
    ],
    more: !!c.more && (!c.cut || cut),
  }
}

/**
 * A fetch word's preview: hover never fetches, so it is this session's cached
 * card, or the name, its kind and `click to open`.
 */
export function fetchPreview(cand: Candidate, card: Card | null): Content {
  if (card)
    return { title: card.title, lines: [...card.meta.map((m) => prose(m, 'label')), ...card.body.map((b) => prose(b))], cite: card.cite ?? '', more: null, reread: false, cut: true }
  const kind = cand.kind === 'option' ? cand.key.split('|')[0]! : cand.kind
  return { title: cand.name, lines: [prose(kind, 'label'), prose('click to open', 'label')], cite: '', more: null, reread: false }
}

files.hooks/look.ts:
// The default look: Alien (1979) computer interfaces meet John Provencher.
// One text system for every surface: readout rules between sections, uppercase
// readouts for labels, values in ink, gauges as glyph runs, one phosphor accent
// for what is live. Pure: no mods API, and nothing reads a sheet; view.ts hands
// in the numbers.
//
// The screen is the terminal: the pane paints no background and sets no theme.
// Ink is the host's foreground (no `color`), dim is `dimColor`; only the raw
// colours below are set. Dark is the intended look; on a light theme
// (`useLight`, from the host's `theme` setting) the accents swap to darker
// shades of the same hues, so they read on a white ground.

import type { TextProps } from 'claude-code'

/**
 * The raw colours. Phosphor and faint are sampled from the workbench mock the
 * owner chose (factory T0037, `B-workbench-green.png`), which Studio
 * (`journal/`) shares, so the two tools have one green.
 */
const DARK = {
  phosphor: '#4af626',
  amber: '#f0a020',
  alert: '#ff3b30',
  cyan: '#3fc8e0',
  violet: '#a07cff',
  faint: '#6a6a6a',
  /** The hover preview's ground (T0093 Layer 3): the pane paints none, and the preview must cover the rows under it. */
  card: '#2b2b3c',
  /**
   * The words on that ground. It is dark on every theme, so its words carry their own
   * light ink rather than the host's, which is near-black on a light theme.
   */
  cardInk: '#ededed',
  cardDim: '#a8a8b8',
}

/**
 * The light theme's accents: the same hues, dark enough for 4.5:1 on white.
 * The neon originals wash out on a light ground (owner, 2026-10-12: "light
 * mode for the d&d pane looks bad, hard to read"). The card keeps its own dark
 * ground and ink on every theme.
 */
const LIGHT: typeof DARK = {
  ...DARK,
  phosphor: '#1a7f0e',
  amber: '#9a5700',
  alert: '#c4231b',
  cyan: '#00728a',
  violet: '#6a3fd6',
  faint: '#767676',
}

/** The colours in use: dark's until `useLight` says the host's theme is light. */
export let TOKENS: Readonly<typeof DARK> = DARK

/** Picks the accents for the host's theme; true for any `light*` theme. */
export function useLight(light: boolean): void {
  TOKENS = light ? LIGHT : DARK
}

/** Whether a `theme` setting value is one of the light themes (`light`, `light-daltonized`, `light-ansi`). */
export const isLightTheme = (value: unknown): boolean => typeof value === 'string' && value.startsWith('light')

/**
 * Faint words (a class line, `KEEPS`, `seen 13:19`, a readout): the host theme's own
 * grey, a theme key, so it reads on a dark or a light ground. `TOKENS.faint` is a raw
 * colour, kept for the pixel art, where a key cannot reach.
 */
export const FAINT_TEXT = 'inactive'

/**
 * A receipt's indent in the transcript: the engine's rows carry a `⏺` and two
 * columns of indent, a hook's row carries no bullet, so the verb sits in the
 * text column (probe run 5 showed the detail at column 0 beside an indented
 * engine block).
 */
export const RECEIPT_INDENT = 2

/**
 * How long a changed value stays inverse after a write. Handoff 17: "one
 * 'flash' frame on a changed value (step C: redraw it inverse once, then
 * normal)."
 */
export const FLASH_MS = 800

/** One glyph pair for every gauge, and `none` for a number never written (never the spent glyph). `▮`/`▯` wait for a live check of the players' fonts. */
export const GAUGE = { full: '█', spent: '░', none: '·' } as const

/** HP's state: phosphor above half, amber to a quarter, alert below. */
export type HpState = 'phosphor' | 'amber' | 'alert'
/** A gauge's full-glyph colour: an HP state, or ink for slots and resources. */
export type Tone = HpState | 'ink'
export type Segment = 'full' | 'spent' | 'temp' | 'none'

export function hpState(current: number, max: number): HpState {
  const frac = max > 0 ? current / max : 0
  return frac > 0.5 ? 'phosphor' : frac >= 0.25 ? 'amber' : 'alert'
}

/**
 * Segments for current/max plus temp: one per hit point while they fit in
 * `room`, else each stands for several. Temp HP follows the maximum.
 */
export function hpSegments(current: number, max: number, temp: number, room: number): Segment[] {
  const total = Math.max(1, max) + Math.max(0, temp)
  const per = Math.max(1, Math.ceil(total / Math.max(1, room)))
  const n = Math.ceil(total / per)
  const maxSegs = Math.ceil(Math.max(1, max) / per)
  const full = Math.min(Math.ceil(Math.max(0, current) / per), maxSegs)
  return Array.from({ length: n }, (_, i): Segment => (i < full ? 'full' : i < maxSegs ? 'spent' : 'temp'))
}

/** `n` segments, the first `full` of them full, the rest spent. */
export const segments = (full: number, n: number): Segment[] =>
  Array.from({ length: n }, (_, i): Segment => (i < full ? 'full' : 'spent'))

/** The band's HP gauge: `round(current / max × cells)` full, the rest spent. */
export function bandSegments(current: number, max: number, cells = 10): Segment[] {
  const frac = max > 0 ? current / max : 0
  return segments(Math.max(0, Math.min(cells, Math.round(frac * cells))), cells)
}

/** A gauge for a number the sheet has never held: `cells` empty, faint segments. */
export const noneSegments = (cells = 10): Segment[] => Array(cells).fill('none')

/** One run of a gauge: the glyphs and the props of the `Text` that draws them. */
export interface Run {
  text: string
  props: TextProps
}

const toneProps = (tone: Tone): TextProps => (tone === 'ink' ? {} : { color: TOKENS[tone] })

/**
 * The `Text` runs for one gauge: full glyphs in the tone's colour, spent ones
 * dim, temp as cyan full glyphs, none as faint dots; empty runs dropped. `spaced` puts a space
 * between glyphs (slot and resource pips).
 */
export function gaugeRuns(segments: Segment[], tone: Tone, opts: { spaced?: boolean } = {}): Run[] {
  const sep = opts.spaced ? ' ' : ''
  const runs: Run[] = []
  const add = (seg: Segment, props: TextProps) => {
    const n = segments.filter((s) => s === seg).length
    if (!n) return
    const glyph = seg === 'spent' ? GAUGE.spent : seg === 'none' ? GAUGE.none : GAUGE.full
    runs.push({ text: (runs.length ? sep : '') + Array(n).fill(glyph).join(sep), props })
  }
  add('full', toneProps(tone))
  add('spent', { dimColor: true })
  add('temp', { color: TOKENS.cyan })
  add('none', { color: TOKENS.faint })
  return runs
}

/**
 * Pips for `left` of `max` in `width` cells: a glyph each with a space between
 * while they fit, else a meter of `width` glyphs without spaces.
 */
export function pipRuns(left: number, max: number, width: number, tone: Tone): Run[] {
  const spaced = max * 2 - 1 <= width
  const n = spaced ? max : width
  const full = spaced ? left : Math.round((width * left) / Math.max(1, max))
  return gaugeRuns(segments(full, n), tone, { spaced })
}

/** A readout rule, `── LABEL ───…`, exactly `columns` characters; `── ───…` without a label. */
export function rule(label: string, columns: number): string {
  const head = label ? `── ${label.toUpperCase()} ` : '── '
  return (head + '─'.repeat(Math.max(0, columns - head.length))).slice(0, columns)
}

files.hooks/lookup.ts:
// Lookups (T0085 stage 1): what the DM or a player types into `[ look up ]`,
// matched against the spells the facts table knows, the 2024 conditions and
// the fight's monsters; and the card a match opens, drawn from the facts row
// at once and from the rules server's answer once a press fetched it. Pure:
// no mods API (register.ts calls the tools, view.ts draws).

import { norm, weaponFact } from './actions.ts'
import { SPELLS, type SpellRow } from './facts.ts'
import { GLOSSARY } from './glossary.ts'

export { norm }

/**
 * A card's subject. `glossary` is drawn from `GLOSSARY` with no fetch; `option`
 * (a feature, feat, species or item, from the sheet's tabs or a glossary link)
 * is fetched by `character_option_get`, its key `kind|name|feature`.
 */
export type Candidate = { name: string; kind: 'spell' | 'condition' | 'monster' | 'glossary' | 'option'; key: string }

export type Card = { title: string; meta: string[]; body: string[]; cite: string | null }

export const CONDITIONS = [
  'Blinded', 'Charmed', 'Deafened', 'Exhaustion', 'Frightened', 'Grappled', 'Incapacitated', 'Invisible',
  'Paralyzed', 'Petrified', 'Poisoned', 'Prone', 'Restrained', 'Stunned', 'Unconscious',
] as const

const SMALL = new Set(['of', 'the', 'and', 'with', 'to', 'from', 'in', 'on'])

/** A facts key's name as a reader writes it: `tasha s hideous laughter` → "Tasha's Hideous Laughter". */
export function displayName(keyName: string): string {
  return keyName
    .replace(/(\w) s\b/g, "$1's")
    .split(' ')
    .map((w, i) => (i > 0 && SMALL.has(w) ? w : w.charAt(0).toUpperCase() + w.slice(1)))
    .join(' ')
}

/** One spell per name: its `|xphb` key when there is one (2024, as `spell_get` defaults), else its first. */
const SPELL_CANDS: Candidate[] = (() => {
  const keys = new Map<string, string>()
  for (const k of Object.keys(SPELLS)) {
    const name = k.slice(0, k.lastIndexOf('|'))
    const had = keys.get(name)
    if (!had || (k.endsWith('|xphb') && !had.endsWith('|xphb'))) keys.set(name, k)
  }
  return [...keys].map(([name, key]) => ({ name: displayName(name), kind: 'spell' as const, key }))
})()

const CONDITION_CANDS: Candidate[] = CONDITIONS.map((name) => ({ name, kind: 'condition', key: norm(name) }))

/** Everything a look can open: the spells, the conditions, and `monsters` (deduped by `norm`). */
export function candidates(monsters: string[]): Candidate[] {
  const seen = new Set<string>()
  const mons: Candidate[] = []
  for (const m of monsters) {
    const key = norm(m)
    if (!key || seen.has(key)) continue
    seen.add(key)
    mons.push({ name: m.trim(), kind: 'monster', key })
  }
  return [...mons, ...SPELL_CANDS, ...CONDITION_CANDS]
}

const KIND_ORDER = { monster: 0, spell: 1, condition: 2, glossary: 3, option: 4 } as const

/** 0 exact, 1 whole-name prefix, 2 word prefix, 3 substring; -1 no match. */
function tier(q: string, name: string): number {
  if (name === q) return 0
  if (name.startsWith(q)) return 1
  if ((' ' + name).includes(' ' + q)) return 2
  if (name.includes(q)) return 3
  return -1
}

/** The best `n` candidates for `query`: exact, prefix, word prefix, substring; ties monsters, spells, conditions, then A–Z. */
export function matches(query: string, cands: Candidate[], n = 5): Candidate[] {
  const q = norm(query)
  if (!q) return []
  return cands
    .map((c) => ({ c, t: tier(q, norm(c.name)) }))
    .filter((x) => x.t >= 0)
    .sort((a, b) => a.t - b.t || KIND_ORDER[a.c.kind] - KIND_ORDER[b.c.kind] || a.c.name.localeCompare(b.c.name))
    .slice(0, n)
    .map((x) => x.c)
}

const ATTACK: Record<string, string> = { m: 'Melee', r: 'Ranged', 'm,r': 'Melee or Ranged', 'r,m': 'Melee or Ranged' }

/**
 * `{@damage 3d8}` → `3d8`, `{@condition prone|xphb}` → `prone`, a stat
 * block's `{@atkr m} {@hit 3}` → `Melee Attack Roll: +3` and `{@h}` → `Hit: `;
 * nested tags from the inside out.
 */
const untag = (s: string) => {
  let out = s
    .replace(/\{@atkr? ([^{}]*)\}/g, (_, k: string) => `${ATTACK[k.trim()] ?? k} Attack Roll:`)
    .replace(/\{@hit (-?\d+)\}/g, (_, n: string) => (n.startsWith('-') ? n : '+' + n))
    .replace(/\{@h\}/g, 'Hit: ')
    .replace(/\{@dc (\d+)\}/g, 'DC $1')
  for (let prev = ''; prev !== out; ) {
    prev = out
    out = out.replace(/\{@\w+ ([^{}|]*)(?:\|[^{}]*)?\}/g, '$1')
  }
  return out
}

const cellText = (v: unknown): string => (typeof v === 'string' ? untag(v) : flatten([v]).join(' '))

/** 5etools entries as plain lines: strings, named entries (`Name. text`), lists (`• `), tables (cells ` | `); the rest skipped. */
export function flatten(entries: unknown): string[] {
  if (!Array.isArray(entries)) return []
  const out: string[] = []
  for (const e of entries) {
    if (typeof e === 'string') {
      out.push(untag(e))
      continue
    }
    if (!e || typeof e !== 'object') continue
    const o = e as Record<string, any>
    if (o.type === 'entries' || o.type === 'item') {
      const lines = flatten(o.entries ?? (o.entry !== undefined ? [o.entry] : []))
      if (o.name) {
        const [first, ...rest] = lines
        out.push(`${untag(String(o.name))}.` + (first ? ' ' + first : ''), ...rest)
      } else out.push(...lines)
    } else if (o.type === 'list') {
      for (const item of o.items ?? []) for (const line of flatten([item])) out.push('• ' + line)
    } else if (o.type === 'table') {
      for (const r of o.rows ?? []) if (Array.isArray(r)) out.push(r.map(cellText).join(' | '))
    }
  }
  return out
}

export const SCHOOLS: Record<string, string> = {
  A: 'Abjuration', C: 'Conjuration', D: 'Divination', E: 'Enchantment', V: 'Evocation', I: 'Illusion', N: 'Necromancy', T: 'Transmutation',
}

/** A cantrip's table (`1:1d10 5:2d10`) as `1d10, 2d10 at 5`; a slot spell's dice as they are. */
const diceText = (dice: string) =>
  dice.includes(':')
    ? dice.split(' ').map((p, i) => {
        const [lv, d] = p.split(':')
        return i ? `${d} at ${lv}` : d
      }).join(', ')
    : dice

/** A spell's facts row as the card's meta: level and school, time, range, components, duration, the roll, dice, damage types. */
function spellMeta(row: SpellRow): string[] {
  const [level, school, time, range, comps, duration, flagText, types, save, dice] = row
  const flags = flagText.split(' ')
  const sch = SCHOOLS[school] ?? school
  const meta = [
    (level === 0 ? `${sch} cantrip` : `Level ${level} ${sch}`) + (flags.includes('ritual') ? ' (ritual)' : ''),
    time,
    range,
    comps.split('').join(', '),
    (flags.includes('conc') ? 'Concentration, ' : '') + duration,
  ]
  if (flags.includes('ranged')) meta.push('ranged spell attack')
  else if (flags.includes('melee')) meta.push('melee spell attack')
  else if (save) meta.push(`${save} save`)
  if (dice) meta.push(diceText(dice))
  if (types) meta.push(types.split(',').join(', '))
  return meta.filter(Boolean)
}

const mod = (score: unknown) => {
  const n = Math.floor((Number(score) - 10) / 2)
  return Number.isFinite(n) ? (n >= 0 ? '+' + n : '−' + -n) : '?'
}

const acText = (ac: unknown) => {
  const first = Array.isArray(ac) ? ac[0] : ac
  return typeof first === 'number' ? String(first) : first && typeof first === 'object' && 'ac' in first ? String((first as any).ac) : '?'
}

const speedText = (s: unknown) => {
  if (typeof s === 'number') return `${s} ft`
  if (!s || typeof s !== 'object') return '?'
  return Object.entries(s as Record<string, any>)
    .filter(([, v]) => typeof v === 'number' || (v && typeof v === 'object' && 'number' in v))
    .map(([k, v]) => `${k === 'walk' ? '' : k + ' '}${typeof v === 'number' ? v : v.number} ft`)
    .join(', ')
}

const crText = (cr: unknown) => (typeof cr === 'string' ? cr : cr && typeof cr === 'object' && 'cr' in cr ? String((cr as any).cr) : '?')

/** A monster's answer as meta lines: AC, HP and formula, speed, the six modifiers, CR. */
function monsterMeta(p: Record<string, any>): string[] {
  const hp = p.hp && typeof p.hp === 'object' ? (p.hp.average !== undefined ? `HP ${p.hp.average}${p.hp.formula ? ` (${p.hp.formula})` : ''}` : `HP ${p.hp.special ?? '?'}`) : 'HP ?'
  return [
    `AC ${acText(p.ac)}`,
    hp,
    `Speed ${speedText(p.speed)}`,
    ['str', 'dex', 'con', 'int', 'wis', 'cha'].map((a) => `${a.toUpperCase()} ${mod(p[a])}`).join(' '),
    `CR ${crText(p.cr)}`,
  ]
}

const ARMOR: Record<string, (ac: unknown) => string> = {
  LA: (ac) => `Light armor, AC ${ac} + Dex`,
  MA: (ac) => `Medium armor, AC ${ac} + Dex (max 2)`,
  HA: (ac) => `Heavy armor, AC ${ac}`,
  S: (ac) => `Shield, AC +${ac}`,
}

const coins = (cp: number) => (cp % 100 === 0 ? `${cp / 100} gp` : cp % 10 === 0 ? `${cp / 10} sp` : `${cp} cp`)

/** A base item's answer as meta lines: a weapon's facts row, or armor's AC and needs; then weight and cost. */
function itemMeta(p: Record<string, any>): string[] {
  const c = p.citation ?? {}
  const meta: string[] = []
  const w = p.weapon && typeof c.name === 'string' ? weaponFact(c.name, c.source, c.edition) : null
  if (w) {
    const [category, kind, dice, type, versatile, props, range, mastery] = w.row
    meta.push(`${category.charAt(0).toUpperCase() + category.slice(1)} ${kind} weapon`, `${dice} ${type}` + (versatile ? ` (${versatile} two-handed)` : ''))
    if (props) meta.push(props.split(',').join(', '))
    if (range) meta.push(`Range ${range} ft`)
    if (mastery) meta.push(`Mastery: ${mastery}`)
  }
  const armor = ARMOR[String(p.type ?? '').split('|')[0]!]
  if (armor) {
    meta.push(armor(p.ac))
    if (p.strength) meta.push(`Str ${p.strength}`)
    if (p.stealth) meta.push('Stealth Disadvantage')
  }
  if (typeof p.weight === 'number') meta.push(`${p.weight} lb`)
  if (typeof p.value === 'number') meta.push(coins(p.value))
  return meta
}

/** A monster's traits, then actions, bonus actions and reactions, each `Name. text`. */
const monsterBody = (p: Record<string, any>) =>
  ['trait', 'action', 'bonus', 'reaction'].flatMap((k) =>
    flatten((Array.isArray(p[k]) ? p[k] : []).map((x: any) => ({ type: 'entries', name: x?.name, entries: x?.entries ?? [] }))),
  )

/** A spell candidate's facts row, for its card's meta before the fetch lands; null for the rest. */
export const factsRow = (cand: Candidate): SpellRow | null => (cand.kind === 'spell' ? SPELLS[cand.key] ?? null : null)

/** The card: the facts row's meta at once (spells), then the server's answer: its name, body and citation. */
export function cardOf(cand: Candidate, payload: unknown, row: SpellRow | null): Card {
  if (cand.kind === 'glossary') {
    const g = GLOSSARY[cand.key]
    const body = g ? g[1].replace(/⟦[^|⟧]*\|([^⟧]*)⟧/g, '$1').split('\n') : []
    return { title: g?.[0] ?? cand.name, meta: [], body, cite: g ? `${g[2]} p${g[3]}, 2024` : null }
  }
  const p = payload && typeof payload === 'object' ? (payload as Record<string, any>) : null
  const c = p?.citation
  const cite = c && typeof c === 'object' && c.source ? `${c.source} p${c.page ?? '?'}, ${c.edition ?? '?'}` : null
  const title = typeof p?.name === 'string' ? p.name : cand.name
  if (cand.kind === 'spell') {
    return { title, meta: row ? spellMeta(row) : [], body: p ? [...flatten(p.entries), ...flatten(p.entriesHigherLevel)] : [], cite }
  }
  if (cand.kind === 'monster') return { title, meta: p ? monsterMeta(p) : [], body: p ? monsterBody(p) : [], cite }
  if (cand.kind === 'option') {
    // A class or subclass feature's answer carries `feature.text`; a species', `traits`
    // (the pressed one, else all of them); an item's, its facts as meta; the rest, `entries`.
    const text = p?.feature?.text
    const name = p?.feature?.name ?? c?.name
    const named = typeof name === 'string' ? name : cand.name
    const traits = Array.isArray(p?.traits) ? p.traits.filter((t: any) => typeof t?.name === 'string' && typeof t?.text === 'string') : []
    if (cand.key.startsWith('species|') && traits.length) {
      const one = traits.find((t: any) => norm(t.name) === norm(cand.name))
      if (one) return { title: one.name, meta: [], body: one.text.split(/\n+/).filter(Boolean), cite }
      return { title: named, meta: [], body: traits.map((t: any) => `${t.name}. ${t.text}`), cite }
    }
    const meta = p && cand.key.startsWith('item|') ? itemMeta(p) : []
    return { title: named, meta, body: typeof text === 'string' ? text.split(/\n+/).filter(Boolean) : p ? flatten(p.entries) : [], cite }
  }
  return { title, meta: [], body: p ? flatten(p.entries) : [], cite }
}

/**
 * Ask Claude's prompt: the subject only (the typed text, or the card's title
 * and cite), the session, and the pane it came from; and `tail`, the heard
 * file's last minute of text, when the party pane has a fresh one. Nothing in it logs.
 */
export function askText({ subject, pane, session, tail }: { subject: string | { title: string; cite: string | null }; pane: 'Party' | 'Sheet'; session: string | null; tail?: string | null }): string {
  const s = session ? ` (${session})` : ''
  const about = typeof subject === 'string' ? `Table question${s}: ${subject}` : `Table question${s} about ${subject.title}` + (subject.cite ? ` (${subject.cite})` : '')
  const heard = tail ? ` Heard at the table in the last minute (local live transcript; names may be misheard): "${tail}".` : ''
  return `${about}, from the ${pane} pane.${heard} Answer from the rules server and cite it, in at most four lines. If the text doesn't settle it, say so and give the options; the DM rules.`
}

// ------------------------------------------------------------------ heard (T0085 stage 2)

/** The live listener's file (capture/live.py): text only, rewritten every few seconds, deleted when it stops. */
export const HEARD_PATH = '/tmp/toa-live/heard.json'
/** A heard file not rewritten for this long is treated as absent. */
const HEARD_STALE_MS = 10 * 60_000

export type HeardItem = { at: number; name: string; kind: 'spell' | 'condition' }
/** The heard file: its items newest first, and the last minute of heard text. */
export type Heard = { updated: number; items: HeardItem[]; tail: string }

/** The heard file's text as a Heard; null when there is none, it does not parse, its `v` is not 1, or it is stale. */
export function asHeard(text: string | null, now: number): Heard | null {
  if (!text) return null
  let j: any
  try {
    j = JSON.parse(text)
  } catch {
    return null
  }
  if (!j || j.v !== 1 || typeof j.updated !== 'number' || now - j.updated > HEARD_STALE_MS || !Array.isArray(j.items)) return null
  const items: HeardItem[] = j.items
    .filter((x: any) => x && typeof x.at === 'number' && typeof x.name === 'string' && (x.kind === 'spell' || x.kind === 'condition'))
    .map((x: any) => ({ at: x.at, name: x.name, kind: x.kind }))
  return { updated: j.updated, items, tail: typeof j.tail === 'string' ? j.tail : '' }
}

files.hooks/receipt.ts:
// A connector call's row in the transcript, as one line of words: a verb
// readout (`WRITE`, `CHECK`, `SPELL`) and the answer, the citation inline as
// the server gave it. The verb and shape come from the output, never the
// input, so a mismatched answer passes; words may come from the input (a
// preview's reason, a create's action). Anything the shapes below do not
// match is `null`: the row stays Claude Code's own.
// Vault receipts describe the request; LOGGED/CLOSED alone are confirmed by
// the answer. The engine's result block is their detail. Interrupted rows pass.
//
// Pure and synchronous: every pane invalidate redraws every connector row
// (`$.ui.invalidate('ui.render')` is plugin-wide). No mods API here.

import { asApplied, asCheck, asGet, describeChange, payloadOf, textOf, type DiffItem, type Finding } from './sheet.ts'

/** The rules connector's tools that draw a receipt; each has a fixture in tests/fixtures/bati. */
export const CONNECTOR =
  /^mcp__.+__(sheet_read|sheet_write|level_up|spell_get|monster_get|character_option_get|condition_search|variantrule_search|book_content_get)$/

/** The vault's tools whose rows draw a receipt during play; `receipt()` draws the Table kinds and the reads. */
export const VAULT = /^mcp__vault__(vault_query|canon_query|draft_write)$/

export interface Receipt {
  verb: string
  body: string
  state: 'running' | 'done' | 'error'
  /** Lines the row cannot hold (findings in words), drawn over the result block in ctrl+o. */
  detail: string[]
}

/** A `ToolUse` row's props, or a `ToolResult`'s with `isRunning: false` and no input. */
export interface Row {
  tool: string
  input?: unknown
  isRunning: boolean
  isErrored: boolean
  isInterrupted?: boolean
  output?: unknown
}

type Sheets = (id: string) => Record<string, any> | undefined

export const isObj = (v: unknown): v is Record<string, any> => !!v && typeof v === 'object' && !Array.isArray(v)
const str = (v: unknown): string | undefined => (typeof v === 'string' ? v : undefined)
const plural = (n: number, one: string, many: string) => `${n} ${n === 1 ? one : many}`

const KIND: Record<string, string> = {
  class: 'CLASS',
  subclass: 'SUBCLASS',
  feat: 'FEAT',
  species: 'SPECIES',
  background: 'BACKGROUND',
  item: 'ITEM',
  optional_feature: 'FEATURE',
  class_spells: 'SPELLS',
}

const FIXED: Record<string, string> = {
  level_up: 'LEVEL UP',
  spell_get: 'SPELL',
  monster_get: 'MONSTER',
  condition_search: 'CONDITION',
  variantrule_search: 'RULE',
  book_content_get: 'BOOK',
}

const READS: Record<string, string> = { get: 'READ', list: 'LIST', history: 'HISTORY', check: 'CHECK', schema: 'SCHEMA' }

const suffix = (tool: string) => tool.match(CONNECTOR)?.[1] ?? tool
const request = (input: unknown): Record<string, any> => (isObj(input) && isObj(input.request) ? input.request : {})
const kindVerb = (input: unknown) => (isObj(input) && KIND[input.kind]) || 'OPTION'

/** The verb a call draws while it runs, from its input alone. */
export function runningVerb(tool: string, input: unknown): string {
  const t = suffix(tool)
  const action = request(input).action
  if (t === 'sheet_read') return READS[action] ?? 'READ'
  if (t === 'sheet_write') return isObj(input) && input.apply === true ? (action === 'create' ? 'CREATE' : 'WRITE') : 'PREVIEW'
  if (t === 'character_option_get') return kindVerb(input)
  return FIXED[t] ?? t.toUpperCase()
}

/** ` · PHB p.186`: the source, and the page unless its evidence is absent; `''` without a source. */
export function cite(c: unknown): string {
  if (!isObj(c) || typeof c.source !== 'string') return ''
  return ` · ${c.source}` + (typeof c.page === 'number' && c.page_evidence !== 'absent' ? ` p.${c.page}` : '')
}

/** `PHB p.186 · Resting > Long Rest`: a citation on its own line, with its section. */
export function citeLine(c: unknown): string {
  const head = cite(c).slice(3)
  return head && isObj(c) && typeof c.section === 'string' ? `${head} · ${c.section}` : head
}

/** Findings in words, warnings first: `⚠ message · PHB p.174 · section`, `· message` for the rest. */
export function findingLines(findings: Finding[]): string[] {
  const line = (f: Finding, mark: string) => {
    const c = citeLine(f.citation)
    return `${mark} ${f.message}` + (c ? ` · ${c}` : '')
  }
  const warn = findings.filter((f) => f.severity === 'warning')
  return [...warn.map((f) => line(f, '⚠')), ...findings.filter((f) => f.severity !== 'warning').map((f) => line(f, '·'))]
}

const done = (verb: string, body: string, detail: string[] = []): Receipt => ({ verb, body, state: 'done', detail })

function firstSentence(text: string): string {
  const m = text.match(/^[\s\S]*?\.(?=\s|$)/)
  return (m ? m[0] : text).slice(0, 200)
}

const validDiff = (v: unknown): v is DiffItem[] => Array.isArray(v) && v.every((x) => isObj(x) && typeof x.path === 'string')

/** The change in words plus the first diff item's rule: `HP 12 → 15 · long rest · PHB p.186`. */
function change(character: string, reason: unknown, diff: DiffItem[], sheetOf: Sheets): string {
  const body = describeChange({ version: 0, at: 0, reason: str(reason) ?? '', diff }, sheetOf(character) ?? {})
  return body + cite(diff[0]?.rule)
}

function sheetRead(d: unknown, sheetOf: Sheets): Receipt | null {
  const got = asGet(d)
  if (got) return done('READ', got.sheet.name)
  const check = asCheck(d)
  if (check) {
    const name = sheetOf(check.character.id)?.name ?? check.character.id
    const w = check.findings.filter((f) => f.severity === 'warning').length
    const i = check.findings.length - w
    const counts = check.findings.length ? `${plural(w, 'warning', 'warnings')} · ${plural(i, 'note', 'notes')}` : 'clean'
    return done('CHECK', `${name} · ${counts}`, findingLines(check.findings))
  }
  if (Array.isArray(d) && d.every((x) => isObj(x) && typeof x.id === 'string' && typeof x.name === 'string'))
    return done('LIST', d.length ? d.map((x) => x.name).join(', ') : 'no sheets')
  if (isObj(d) && isObj(d.character) && typeof d.character.id === 'string' && Array.isArray(d.versions)) {
    const name = sheetOf(d.character.id)?.name ?? d.character.id
    return done('HISTORY', `${name} · ${plural(d.versions.length, 'version', 'versions')}`)
  }
  if (isObj(d) && isObj(d.schema) && (d.schema.$schema || d.schema.properties)) return done('SCHEMA', 'sheet')
  return null
}

function sheetWrite(d: unknown, input: unknown, sheetOf: Sheets): Receipt | null {
  const req = request(input)
  const w = asApplied(d)
  if (w) {
    const allAdds = w.diff.every((x) => !('from' in x))
    if ((allAdds && !sheetOf(w.character)) || req.action === 'create') {
      const parts = [w.name ?? w.character, str(req.reason), plural(w.diff.length, 'field', 'fields')]
      return done('CREATE', parts.filter((p) => p !== undefined).join(' · '))
    }
    const rules = [...new Set(w.diff.map((x) => citeLine(x.rule)).filter((l) => l))]
    return done('WRITE', change(w.character, req.reason, w.diff, sheetOf), rules.length > 1 ? rules : [])
  }
  if (isObj(d) && d.preview === true && typeof d.character === 'string' && validDiff(d.diff)) {
    const findings: Finding[] = Array.isArray(d.findings) ? d.findings.filter((f: unknown) => isObj(f) && typeof f.message === 'string') : []
    const warnings = findings.filter((f) => f.severity === 'warning')
    const body = change(d.character, req.reason, d.diff, sheetOf)
    return done('PREVIEW', body + (warnings.length ? ' · ' + plural(warnings.length, 'warning', 'warnings') : ''), findingLines(warnings))
  }
  return null
}

function lookup(t: string, d: unknown, input: unknown): Receipt | null {
  if (!isObj(d)) return null
  if (t === 'level_up') {
    const l = d.level
    if (!isObj(l) || typeof l.class !== 'string' || typeof l.from !== 'number' || typeof l.to !== 'number') return null
    const names = Array.isArray(d.features) ? d.features.map((f: any) => str(f?.name)).filter((n: unknown) => n) : []
    return done(FIXED[t]!, `${l.class} ${l.from} → ${l.to}` + (names.length ? ' · ' + names.join(', ') : '') + cite(d.citation))
  }
  if (t === 'condition_search' || t === 'variantrule_search') {
    const results = Array.isArray(d.results) ? d.results.filter((r: unknown) => isObj(r) && typeof r.name === 'string') : []
    if (!results.length) return null
    if (results.length === 1) return done(FIXED[t]!, results[0].name + cite(results[0].citation))
    return done(FIXED[t]!, results.slice(0, 3).map((r: any) => r.name).join(', ') + ` · ${results.length} results`)
  }
  if (t === 'book_content_get') {
    const c = d.citation
    if (!isObj(c) || typeof c.source !== 'string') return null
    if (typeof c.section === 'string') return done('BOOK', c.section + cite(c))
    return Array.isArray(d.sections) ? done('BOOK', `${c.source} · ${plural(d.sections.length, 'section', 'sections')}`) : null
  }
  if (!isObj(d.citation) || typeof d.citation.name !== 'string') return null
  if (t === 'character_option_get') return done(kindVerb(input), d.citation.name + cite(d.citation))
  if (t === 'spell_get' || t === 'monster_get') return done(FIXED[t]!, d.citation.name + cite(d.citation))
  return null
}

/** Vault reads say what was asked; only a confirmed Table write says LOGGED/CLOSED. */
function vaultReceipt(t: string, row: Row): Receipt | null {
  const input = isObj(row.input) ? row.input : {}
  const req = request(row.input)
  const write = t === 'draft_write'
  const note = input.kind === 'table-note'
  let verb: string
  let body: string
  if (write) {
    if (!note && input.kind !== 'table-close') return null
    if (typeof input.text !== 'string' || typeof input.session !== 'string') return null
    verb = note ? 'LOGGED' : 'CLOSED'
    body = note ? input.text : `${input.session} · ${input.text}`
  } else if (t === 'vault_query') {
    if (typeof req.action !== 'string') return null
    verb = 'VAULT'
    const arg = [req.id, req.name, req.npc, req.query, req.text, req.since, req.session].find((v) => typeof v === 'string')
    body = req.action + (arg === undefined ? '' : ` ${arg}`)
  } else {
    verb = 'CANON'
    if (req.action === 'search' && typeof req.query === 'string')
      body = `search "${req.query}"` + (typeof req.book === 'string' ? ` · ${req.book}` : '')
    else if (req.action === 'page' && typeof req.book === 'string' && typeof req.printed_page === 'number')
      body = `${req.book} p.${req.printed_page}`
    else return null
  }
  if (row.isRunning && row.output === undefined)
    return { verb: write ? (note ? 'LOG' : 'CLOSE') : verb, body: (write ? input.text : body) + ' …', state: 'running', detail: [] }
  if (row.isErrored) {
    const text = textOf(row.output)
    return text ? { verb: write ? 'REFUSED' : 'ERROR', body: firstSentence(text), state: 'error', detail: [] } : null
  }
  const p = payloadOf(row.output)
  if (!p || !('data' in p)) return null
  if (write && (!isObj(p.data) || p.data.wrote !== true)) return null
  if (t === 'canon_query' && req.action === 'search' && isObj(p.data) && p.data.total === 0) body += ' · NO HIT'
  return done(verb, body)
}

/** The receipt for a connector row, or null when the row should stay Claude Code's. */
export function receipt(row: Row, sheetOf: Sheets): Receipt | null {
  const v = row.tool.match(VAULT)
  if (v && !row.isInterrupted) return vaultReceipt(v[1]!, row)
  const m = row.tool.match(CONNECTOR)
  if (!m || row.isInterrupted) return null
  const t = m[1]!
  const sheetTool = t === 'sheet_read' || t === 'sheet_write'
  if (row.isRunning && row.output === undefined) {
    const req = request(row.input)
    const i = isObj(row.input) ? row.input : {}
    const words = [req.reason, req.action, i.name, i.query, i.section, i.source, i.class].find((w) => typeof w === 'string') ?? t
    return { verb: runningVerb(row.tool, row.input), body: words + ' …', state: 'running', detail: [] }
  }
  if (row.isErrored) {
    const text = textOf(row.output)
    if (!text) return null
    const body = firstSentence(text)
    return { verb: sheetTool ? 'REFUSED' : 'ERROR', body, state: 'error', detail: text.length > body.length ? [text] : [] }
  }
  const p = payloadOf(row.output)
  if (!p || !('data' in p)) return null
  if (t === 'sheet_read') return sheetRead(p.data, sheetOf)
  if (t === 'sheet_write') return sheetWrite(p.data, row.input, sheetOf)
  return lookup(t, p.data, row.input)
}

